# %% [markdown]
# ## Diagnostic 1: teacher-forced `dec_val` loss and token accuracy

# %%
@torch.no_grad()
def teacher_forced(index, n_batches=24, batch=64):
    rng = np.random.default_rng(SEED + 1)
    order = p3d.epoch_order(len(index), rng, batch, np.diff(index.tok_off))[:n_batches]
    tot, ntok, ncor = 0.0, 0, 0
    for i, ids in enumerate(order):
        b = p3d.make_batch(index, ids, STORE, np.random.default_rng(SEED + 100 + i),
                           max_spec=p3d.MAX_SPEC_PER_MOL, ce_dropout=0.0, pad_id=VOCAB.pad_id,
                           sos_id=VOCAB.sos_id, eos_id=VOCAB.eos_id)
        d = {k: torch.from_numpy(v).to(DEV) for k, v in b.items()}
        mem, pad = MODEL.build_memory(d["emb"], d["adduct"], d["ce"], d["fvec"], d["spec_mask"])
        logits = MODEL(d["tgt"][:, :-1], mem, pad)
        gold = d["tgt"][:, 1:]
        keep = gold != VOCAB.pad_id
        loss = torch.nn.functional.cross_entropy(
            logits.reshape(-1, logits.shape[-1]).float(), gold.reshape(-1),
            ignore_index=VOCAB.pad_id)
        tot += float(loss) * int(keep.sum())
        ntok += int(keep.sum())
        ncor += int(((logits.argmax(-1) == gold) & keep).sum())
    return tot / max(ntok, 1), ncor / max(ntok, 1)


t0 = time.time()
tf_loss, tf_acc = teacher_forced(VAL_IDX)
EVAL["teacher_forced"] = dict(dec_val_loss=tf_loss, dec_val_token_acc=tf_acc)
