# %% [markdown]
# ## Generation, resumable
#
# One function drives all three arms so they cannot differ in anything but the search itself.

# %%
ARMS = {
    "prefix_seeded": lambda mem, pad, f, s: nd.search_prefix_seeded(
        MODEL, mem, f, TABLE, mem_pad=pad, l_seed=L_SEED, k_roots=K_ROOTS, m_rollout=M_ROLLOUT,
        temperature=TEMPERATURE, top_p=TOP_P, max_len=MAX_LEN, seed=SEED, stats=s),
    "masked_beam": lambda mem, pad, f, s: nd.search_masked_beam(
        MODEL, mem, f, TABLE, mem_pad=pad, beam=BEAM, max_len=MAX_LEN, alpha=0.0, stats=s),
    "diverse_beam": lambda mem, pad, f, s: nd.search_diverse_beam(
        MODEL, mem, f, TABLE, mem_pad=pad, beam=BEAM, alpha=ALPHA_DIVERSE, max_len=MAX_LEN, stats=s),
}


def generate(arm, queries, tag, log_every=25):
    """Run one arm over `queries`, flushing to Drive every CHUNK_MOL molecules. Resumes."""
    store = p3e.ChunkStore(CANDS, tag, chunk=CHUNK_MOL)
    done = store.done()
    todo = [q for q in queries if q["molecule_id"] not in done]
    if done:
        print(f"[{tag}] resuming: {len(done)} done, {len(todo)} to go")
    t0 = time.time()
    for i, q in enumerate(todo, 1):
        st = nd.new_funnel()
        tq = time.time()
        mem, pad = p3e.query_memory(MODEL, q, STORE, DEV, torch)
        try:
            cands = ARMS[arm](mem, pad, q["formula"], st)
        except Exception as e:                     # one bad molecule must not lose the whole run
            print(f"[{tag}] {q['molecule_id']} failed: {type(e).__name__}: {e}", flush=True)
            cands = []
        store.add(q["molecule_id"], cands, st, time.time() - tq)
        if i % log_every == 0 or i == len(todo):
            el = time.time() - t0
            print(f"[{tag}] {i}/{len(todo)}  {el / i:.2f}s/mol  "
                  f"eta {(len(todo) - i) * el / i / 60:.1f} min", flush=True)
    store.flush(extra_done=[q["molecule_id"] for q in todo])
    return store


def score(arm_store, queries, label):
    cands = arm_store.load()
    scored = [p3e.score_molecule(q, cands.get(q["molecule_id"], [])) for q in queries]
    return scored, p3e.summarise(scored, label)

# %% [markdown]
# ## The bake-off on the fixed 300-molecule `dec_val` subset

# %%
BAKE, BAKE_SCORED = {}, {}
for arm in ARMS:
    s = generate(arm, Q_VAL, f"{arm}_dec_val")
    sc, summ = score(s, Q_VAL, f"dec_val|{arm}")
    fn = s.funnels()
    summ["seconds_per_mol"] = float(fn["seconds"].mean()) if len(fn) else None
    for k in ("sequences", "eos", "valid", "unique", "dead", "truncated"):
        if len(fn) and k in fn:
            summ[f"funnel_{k}"] = float(fn[k].mean())
    BAKE[arm], BAKE_SCORED[arm] = summ, sc
    print(f"\n{arm:14} median maxTan {summ['median_maxtan_maxmin']:.4f} (maxmin) / "
          f"{summ['median_maxtan_logp']:.4f} (logp)  exact@25 {summ['exact25_maxmin']:.4f}  "
          f"cands/mol {summ['median_n_cands']:.0f}  {summ['seconds_per_mol']:.2f}s/mol")
EVAL["bake_off"] = BAKE
WINNER, WIN_VAL = p3e.pick_winner(BAKE)
EVAL["winner"] = dict(arm=WINNER, median_maxtan_maxmin=WIN_VAL)
print("\n" + "=" * 88)
print(f"BAKE-OFF WINNER: {WINNER}  (median top-25 max Tanimoto {WIN_VAL:.4f} on dec_val, maxmin)")
print("=" * 88)
save_eval()

# %% [markdown]
# ## The winner on the cohorts
#
# `pseudo_c3` carries the G3 verdict; `ts_dec` is the instrument-shift check and is reported
# separately. They are **never** pooled (A-G1.1).

# %%
COHORTS = {}
for label, queries in [("pseudo_c3", Q_C3), ("ts_dec", Q_TS)]:
    s = generate(WINNER, queries, f"{WINNER}_{label}")
    sc, summ = score(s, queries, f"{label}|{WINNER}")
    fn = s.funnels()
    summ["seconds_per_mol"] = float(fn["seconds"].mean()) if len(fn) else None
    for k in ("sequences", "eos", "valid", "unique", "dead", "truncated"):
        if len(fn) and k in fn:
            summ[f"funnel_{k}"] = float(fn[k].mean())
    COHORTS[label] = summ
    EVAL.setdefault("splits", {})[label] = p3e.split_summaries(sc, label)
    pd.DataFrame(sc).to_parquet(CANDS / f"scored_{WINNER}_{label}.parquet", index=False)
    print(f"\n{label:10} n={summ['n']}  median maxTan {summ['median_maxtan_maxmin']:.4f} "
          f"(maxmin) / {summ['median_maxtan_logp']:.4f} (logp)")
    print(f"{'':10} exact@1/10/25 {summ['exact1_maxmin']:.4f} / {summ['exact10_maxmin']:.4f} / "
          f"{summ['exact25_maxmin']:.4f}   cands/mol median {summ['median_n_cands']:.0f}  "
          f"zero-cand {summ['zero_cand_share']:.3f}")
EVAL["cohorts"] = COHORTS
EVAL["finished"] = time.strftime("%Y-%m-%d %H:%M")
save_eval()

